        elif f["subject_type"] == "RESTAURANT":
            rest = store.restaurants.get(f["subject_id"])
            if rest is not None:
                rest["pending_settlement_cents"] += amt
                rest["version"] += 1
                rest["updated_at"] = now_iso
        return success_object(store.clock, fine_out(f))

