"""Minimal self-test harness.

Each test registers via @test(category). The runner spins up a fresh Flask app
per test, then invokes via Flask's test client. We deliberately avoid pytest /
unittest dependencies so the harness runs against the actual implementation
with zero extra moving parts.
"""
from __future__ import annotations

import json
import sys
import time
import traceback
from dataclasses import dataclass, field
from typing import Callable

from server.app import create_app


@dataclass
class Test:
    category: str
    name: str
    fn: Callable


_tests: list[Test] = []


def test(category: str):
    def deco(fn):
        _tests.append(Test(category=category, name=fn.__name__, fn=fn))
        return fn

    return deco


@dataclass
class Result:
    name: str
    category: str
    passed: bool
    err: str = ""


class TestApp:
    """Wraps a fresh Flask app + test client and provides helpers."""

    def __init__(self):
        self.app = create_app()
        self.client = self.app.test_client()
        self.store = self.app.config["STORE"]

    def request(self, method, path, *, user_id=None, role=None, json_body=None, params=None):
        headers = {}
        if user_id is not None:
            headers["X-User-ID"] = user_id
        if role is not None:
            headers["X-User-Role"] = role
        if json_body is not None:
            headers["Content-Type"] = "application/json"
            data = json.dumps(json_body)
        else:
            data = None
        resp = self.client.open(
            path, method=method, headers=headers, data=data, query_string=params
        )
        try:
            body = json.loads(resp.data.decode("utf-8")) if resp.data else None
        except Exception:
            body = {"_raw": resp.data.decode("utf-8", "replace")}
        return resp.status_code, body

    def admin(self, method, path, **kw):
        return self.request(method, path, user_id="admin1", role="PlatformAdmin", **kw)

    def cs(self, method, path, **kw):
        return self.request(method, path, user_id="cs1", role="CustomerService", **kw)


def expect(cond, msg=""):
    if not cond:
        raise AssertionError(msg or "expectation failed")


def expect_eq(a, b, msg=""):
    if a != b:
        raise AssertionError(f"{msg}: expected {b!r}, got {a!r}")


def expect_err(resp_tuple, error_id: str, http: int | None = None):
    code, body = resp_tuple
    if body is None:
        raise AssertionError(f"expected error {error_id}, got empty body (status={code})")
    got_id = body.get("data", {}).get("error_id")
    if got_id != error_id:
        raise AssertionError(
            f"expected error_id={error_id}, got {got_id} (status={code}, body={body})"
        )
    if http is not None and code != http:
        raise AssertionError(f"expected http {http}, got {code} for error {error_id}")


def run_all() -> int:
    results: list[Result] = []
    by_cat: dict[str, list[Result]] = {}
    started = time.time()
    for t in _tests:
        try:
            app = TestApp()
            t.fn(app)
            results.append(Result(t.name, t.category, True))
        except Exception as e:
            err = "".join(traceback.format_exception(e))
            results.append(Result(t.name, t.category, False, err))
        by_cat.setdefault(t.category, []).append(results[-1])
    elapsed = time.time() - started

    total = len(results)
    failed = [r for r in results if not r.passed]
    for cat, rs in by_cat.items():
        pn = sum(1 for r in rs if r.passed)
        print(f"== {cat}: {pn}/{len(rs)} passed ==")
        for r in rs:
            mark = "PASS" if r.passed else "FAIL"
            print(f"  [{mark}] {r.name}")
            if not r.passed:
                print(r.err)
    print(f"\nTotal {total - len(failed)}/{total} passed in {elapsed:.2f}s")
    return 0 if not failed else 1

"""Fine query + waive endpoints."""
from __future__ import annotations

from flask import Blueprint, g, request

from ..auth import require_role
from ..envelope import success_list, success_object
from ..errors import ApiError
from ..pagination import page_slice, parse_pagination
from ..serializers import fine_out


bp = Blueprint("fines", __name__, url_prefix="/api")


@bp.get("/fines/<fid>")
def read_fine(fid: str):
    require_role("PlatformAdmin", "CustomerService", "Rider", "Restaurant", "Customer")
    store = g.store
    f = store.fines.get(fid)
    if not f:
        raise ApiError("ERR_NOT_FOUND")
    if g.user_role in ("Rider", "Restaurant", "Customer"):
        if f["subject_id"] != g.user_id:
            raise ApiError("ERR_FORBIDDEN")
    return success_object(store.clock, fine_out(f))


@bp.get("/fines")
def list_fines():
    require_role("PlatformAdmin", "CustomerService", "Rider", "Restaurant", "Customer")
    store = g.store
    limit, offset = parse_pagination()
    subject_type = request.args.get("subject_type")
    subject_id = request.args.get("subject_id")
    settlement_status = request.args.get("settlement_status")
    if g.user_role in ("Rider", "Restaurant", "Customer"):
        if subject_id is not None and subject_id != g.user_id:
            raise ApiError("ERR_FORBIDDEN")
        subject_id = g.user_id
    rows = list(store.fines.values())
    if subject_type:
        rows = [f for f in rows if f["subject_type"] == subject_type]
    if subject_id:
        rows = [f for f in rows if f["subject_id"] == subject_id]
    if settlement_status:
        rows = [f for f in rows if f["settlement_status"] == settlement_status]
    page, total = page_slice(rows, limit=limit, offset=offset)
    return success_list(
        store.clock, [fine_out(f) for f in page], limit=limit, offset=offset, total_count=total
    )


@bp.post("/fines/<fid>/waive")
def waive_fine(fid: str):
    require_role("CustomerService", "PlatformAdmin")
    store = g.store
    with store.lock:
        f = store.fines.get(fid)
        if not f:
            raise ApiError("ERR_NOT_FOUND")
        if f["settlement_status"] != "PENDING":
            raise ApiError("ERR_INVALID_STATE")
        now_iso = store.now_iso()
        f["settlement_status"] = "WAIVED"
        amt = f["amount_cents"]
        if f["subject_type"] == "RIDER":
            rider = store.riders.get(f["subject_id"])
            if rider is not None:
                rider["wallet_balance_cents"] += amt
                rider["version"] += 1
                rider["updated_at"] = now_iso
                from ..bonus import recompute_rider_metrics

                recompute_rider_metrics(rider)
        elif f["subject_type"] == "CUSTOMER":
            cust = store.customers.get(f["subject_id"])
            if cust is not None:
                cust["credit_balance_cents"] += amt
                cust["version"] += 1
                cust["updated_at"] = now_iso
        elif f["subject_type"] == "RESTAURANT":
            rest = store.restaurants.get(f["subject_id"])
            if rest is not None:
                rest["pending_settlement_cents"] += amt
                rest["version"] += 1
                rest["updated_at"] = now_iso
        return success_object(store.clock, fine_out(f))

"""Work-order endpoints."""
from __future__ import annotations

from flask import Blueprint, g, request

from ..auth import require_role
from ..envelope import success_object
from ..errors import ApiError
from ..ids import new_uuid
from ..serializers import work_order_out
from ..validation import ensure_dict, optional_str, require_str


bp = Blueprint("work_orders", __name__, url_prefix="/api")


_CATEGORIES = {
    "DELIVERY_LATE",
    "FOOD_QUALITY",
    "MISSING_ITEM",
    "RIDER_BEHAVIOR",
    "RESTAURANT_BEHAVIOR",
    "PAYMENT_ISSUE",
    "OTHER",
}

_ROLES_TO_OPENER = {
    "Customer": "CUSTOMER",
    "Rider": "RIDER",
    "Restaurant": "RESTAURANT",
    "CustomerService": "CUSTOMER_SERVICE",
    "PlatformAdmin": "CUSTOMER_SERVICE",  # admin opens on behalf — recorded as CS
}


@bp.post("/work-orders")
def open_work_order():
    require_role("Customer", "Rider", "Restaurant", "CustomerService", "PlatformAdmin")
    store = g.store
    body = ensure_dict(request.get_json(silent=True) or {})
    category = require_str(body, "category")
    if category not in _CATEGORIES:
        raise ApiError("ERR_VALIDATION", "invalid category")
    related_order_id = optional_str(body, "related_order_id")
    related_return_id = optional_str(body, "related_return_id")
    with store.lock:
        if related_order_id and related_order_id not in store.orders:
            raise ApiError("ERR_NOT_FOUND")
        if related_return_id and related_return_id not in store.returns:
            raise ApiError("ERR_NOT_FOUND")
        opened_by_role = _ROLES_TO_OPENER[g.user_role]
        opened_by_id = g.user_id
        wid = new_uuid()
        now_iso = store.now_iso()
        wo = {
            "id": wid,
            "opened_by_role": opened_by_role,
            "opened_by_id": opened_by_id,
            "category": category,
            "related_order_id": related_order_id,
            "related_return_id": related_return_id,
            "status": "OPEN",
            "resolution_notes": None,
            "assigned_cs_user_id": None,
            "created_at": now_iso,
            "updated_at": now_iso,
            "version": 1,
        }
        store.work_orders[wid] = wo
        return success_object(store.clock, work_order_out(wo), status=201)


@bp.get("/work-orders/<wid>")
def read_work_order(wid: str):
    require_role("PlatformAdmin", "CustomerService", "Customer", "Rider", "Restaurant")
    store = g.store
    wo = store.work_orders.get(wid)
    if not wo:
        raise ApiError("ERR_NOT_FOUND")
    # Visibility: non-opaque roles see only their own opener-marked tickets.
    if g.user_role in ("Customer", "Rider", "Restaurant"):
        if wo["opened_by_id"] != g.user_id:
            raise ApiError("ERR_FORBIDDEN")
    return success_object(store.clock, work_order_out(wo))


@bp.post("/work-orders/<wid>/assign")
def assign_work_order(wid: str):
    require_role("CustomerService", "PlatformAdmin")
    store = g.store
    with store.lock:
        wo = store.work_orders.get(wid)
        if not wo:
            raise ApiError("ERR_NOT_FOUND")
        if wo["status"] != "OPEN":
            raise ApiError("ERR_INVALID_STATE")
        wo["assigned_cs_user_id"] = g.user_id
        wo["status"] = "UNDER_REVIEW"
        wo["version"] += 1
        wo["updated_at"] = store.now_iso()
        return success_object(store.clock, work_order_out(wo))


@bp.post("/work-orders/<wid>/request-info")
def request_info(wid: str):
    require_role("CustomerService", "PlatformAdmin")
    store = g.store
    with store.lock:
        wo = store.work_orders.get(wid)
        if not wo:
            raise ApiError("ERR_NOT_FOUND")
        if wo["status"] != "UNDER_REVIEW":
            raise ApiError("ERR_INVALID_STATE")
        wo["status"] = "AWAITING_INFO"
        wo["version"] += 1
        wo["updated_at"] = store.now_iso()
        return success_object(store.clock, work_order_out(wo))


@bp.post("/work-orders/<wid>/submit-info")
def submit_info(wid: str):
    require_role("Customer", "Rider", "Restaurant")
    store = g.store
    with store.lock:
        wo = store.work_orders.get(wid)
        if not wo:
            raise ApiError("ERR_NOT_FOUND")
        if wo["opened_by_id"] != g.user_id:
            raise ApiError("ERR_FORBIDDEN")
        if wo["status"] != "AWAITING_INFO":
            raise ApiError("ERR_INVALID_STATE")
        wo["status"] = "UNDER_REVIEW"
        wo["version"] += 1
        wo["updated_at"] = store.now_iso()
        return success_object(store.clock, work_order_out(wo))


@bp.post("/work-orders/<wid>/resolve")
def resolve_work_order(wid: str):
    require_role("CustomerService", "PlatformAdmin")
    store = g.store
    body = ensure_dict(request.get_json(silent=True) or {})
    notes = require_str(body, "resolution_notes", max_len=2000)
    with store.lock:
        wo = store.work_orders.get(wid)
        if not wo:
            raise ApiError("ERR_NOT_FOUND")
        if wo["status"] not in ("UNDER_REVIEW", "ESCALATED"):
            raise ApiError("ERR_INVALID_STATE")
        if wo["assigned_cs_user_id"] is None:
            raise ApiError("ERR_INVALID_STATE")
        # Gate on linked Return status.
        if wo.get("related_return_id"):
            r = store.returns.get(wo["related_return_id"])
            if r is None:
                raise ApiError("ERR_NOT_FOUND")
            if r["status"] not in ("APPROVED", "REJECTED"):
                raise ApiError("ERR_RELATED_RETURN_UNRESOLVED")
        wo["resolution_notes"] = notes
        wo["status"] = "RESOLVED"
        wo["version"] += 1
        wo["updated_at"] = store.now_iso()
        return success_object(store.clock, work_order_out(wo))


@bp.post("/work-orders/<wid>/escalate")
def escalate_work_order(wid: str):
    require_role("CustomerService", "PlatformAdmin")
    store = g.store
    with store.lock:
        wo = store.work_orders.get(wid)
        if not wo:
            raise ApiError("ERR_NOT_FOUND")
        if wo["status"] != "UNDER_REVIEW":
            raise ApiError("ERR_INVALID_STATE")
        wo["status"] = "ESCALATED"
        wo["version"] += 1
        wo["updated_at"] = store.now_iso()
        return success_object(store.clock, work_order_out(wo))


@bp.post("/work-orders/<wid>/close")
def close_work_order(wid: str):
    require_role("CustomerService", "PlatformAdmin")
    store = g.store
    with store.lock:
        wo = store.work_orders.get(wid)
        if not wo:
            raise ApiError("ERR_NOT_FOUND")
        if wo["status"] != "RESOLVED":
            raise ApiError("ERR_INVALID_STATE")
        wo["status"] = "CLOSED"
        wo["version"] += 1
        wo["updated_at"] = store.now_iso()
        return success_object(store.clock, work_order_out(wo))

